var businessDB = {
    topicTitles: {
        topic1: "Маркетинг и продажи",
        topic2: "Финансы, учёт и налоги",
        topic3: "Право, документы и формы бизнеса",
        topic4: "IT, цифра и аналитика",
        topic5: "Управление, HR и бизнес-процессы",
        topic6: "Экономика, рынки и инвестиции"
    },

    topic1: [
        { word: "AIDA", trans: "Модель маркетинга: Attention (внимание), Interest (интерес), Desire (желание), Action (действие). Описывает путь клиента от знакомства с продуктом до покупки." },
        { word: "B2B", trans: "Business-to-Business — модель бизнеса, где компании продают товары или услуги другим компаниям (например, поставка сырья на завод)." },
        { word: "B2C", trans: "Business-to-Consumer — модель бизнеса, где компании продают товары или услуги конечным потребителям (розничная торговля)." },
        { word: "BPM-система", trans: "Система управления бизнес-процессами (Business Process Management). Программное обеспечение для моделирования, автоматизации и контроля процессов компании." },
        { word: "Call to action (CTA)", trans: "Призыв к действию — элемент рекламы или лендинга, побуждающий пользователя совершить целевое действие («Купить», «Подписаться»)." },
        { word: "CPA", trans: "Cost Per Action — стоимость целевого действия. Модель оплаты рекламы, при которой рекламодатель платит за конкретное действие пользователя (покупку, регистрацию)." },
        { word: "CRM-система", trans: "Система управления взаимоотношениями с клиентами (Customer Relationship Management). Программа для хранения данных о клиентах, истории взаимодействий и автоматизации продаж." },
        { word: "CustDev", trans: "Customer Development — методология создания продуктов через глубинные интервью с потенциальными клиентами для проверки гипотез до начала разработки." },
        { word: "E-commerce", trans: "Электронная коммерция — покупка и продажа товаров и услуг через интернет (интернет-магазины, маркетплейсы)." },
        { word: "GR", trans: "Government Relations — взаимодействие компании с органами государственной власти для защиты своих интересов и лоббирования." },
        { word: "HoReCa", trans: "Hotel, Restaurant, Catering/Cafe — сектор индустрии гостеприимства (отели, рестораны, кейтеринг)." },
        { word: "MVP", trans: "Minimum Viable Product — минимально жизнеспособный продукт. Версия продукта с базовым набором функций, достаточным для выхода на рынок и сбора обратной связи." },
        { word: "P2P-торговля", trans: "Peer-to-Peer — модель торговли, где физические лица продают товары или услуги напрямую друг другу без посредников (Avito, BlaBlaCar)." },
        { word: "Push-уведомления", trans: "Всплывающие сообщения, которые приложение или сайт отправляет пользователю на устройство для привлечения внимания." },
        { word: "ROMI", trans: "Return on Marketing Investment — возврат маркетинговых инвестиций. Показатель эффективности маркетинговых затрат: (прибыль от маркетинга − затраты) / затраты × 100%." },
        { word: "RSS-лента", trans: "Really Simple Syndication — формат экспорта контента, позволяющий пользователям подписываться на обновления сайтов и получать их в одном месте." },
        { word: "SWOT-анализ", trans: "Метод стратегического планирования: анализ Strengths (сильные стороны), Weaknesses (слабые стороны), Opportunities (возможности), Threats (угрозы)." },
        { word: "ABC-анализ", trans: "Метод классификации ресурсов по степени важности: A (наиболее ценные, 20% дают 80% результата), B (средние), C (наименее значимые)." },
        { word: "ATL-реклама", trans: "Above The Line — реклама в традиционных медиа (ТВ, радио, пресса, наружная реклама), направленная на массовую аудиторию." },
        { word: "BTL-маркетинг", trans: "Below The Line — маркетинговые коммуникации, направленные на узкую аудиторию (промо-акции, директ-мейл, мерчандайзинг, события)." },
        { word: "CJM", trans: "Customer Journey Map — карта пути клиента. Визуализация всех точек контакта клиента с брендом от первого касания до покупки и после неё." },
        { word: "CPC", trans: "Cost Per Click — стоимость клика. Модель оплаты рекламы, при которой рекламодатель платит за каждый переход пользователя по объявлению." },
        { word: "CTOR", trans: "Click-To-Open Rate — отношение числа уникальных кликов к числу открытых писем в email-рассылке. Показывает вовлечённость тех, кто открыл письмо." },
        { word: "CRM-маркетинг", trans: "Маркетинг, основанный на данных из CRM-системы: персонализированные коммуникации с клиентами на основе их поведения и истории покупок." },
        { word: "CTR", trans: "Click-Through Rate — кликабельность. Отношение числа кликов по объявлению к числу его показов, выраженное в процентах." },
        { word: "Dark Store", trans: "Магазин-склад, закрытый для обычных покупателей, откуда курьеры собирают и доставляют заказы (модель быстрой доставки)." },
        { word: "GRP", trans: "Gross Rating Points — суммарный рейтинг пунктов. Показатель охвата рекламной кампании: сумма рейтингов всех выходов рекламы." },
        { word: "HADI-цикл", trans: "Hypothesis-Action-Data-Insights — цикл проверки гипотез: выдвижение гипотезы, действие, сбор данных, выводы. Используется в agile-развитии продукта." },
        { word: "IRR", trans: "Internal Rate of Return — внутренняя норма доходности. Ставка дисконтирования, при которой чистая приведённая стоимость (NPV) проекта равна нулю." },
        { word: "NFT", trans: "Non-Fungible Token — невзаимозаменяемый токен. Уникальный цифровой сертификат права собственности на объект (арт, коллекционный предмет), хранящийся в блокчейне." },
        { word: "POS-материалы", trans: "Point of Sale materials — рекламные материалы в местах продаж (стойки, воблеры, постеры, ценники), стимулирующие покупку." },
        { word: "RFM-анализ", trans: "Recency, Frequency, Monetary — метод сегментации клиентов по давности последней покупки, частоте покупок и сумме потраченных денег." },
        { word: "SKU", trans: "Stock Keeping Unit — единица складского учёта. Уникальный идентификатор конкретной товарной позиции (например, «кофе 250 г арабика»)." },
        { word: "Tone of Voice", trans: "Tone of Voice — тональность коммуникации бренда. Стиль, манера и эмоциональная окраска, с которой бренд общается с аудиторией." },
        { word: "Agile", trans: "Гибкая методология управления проектами, основанная на коротких циклах (спринтах), адаптивности и тесном взаимодействии команды с заказчиком." },
        { word: "Big Data", trans: "Большие данные — совокупность огромных массивов структурированной и неструктурированной информации, обрабатываемых для выявления закономерностей и трендов." },
        { word: "CAC", trans: "Customer Acquisition Cost — стоимость привлечения клиента. Общие затраты на маркетинг и продажи, делённые на число новых клиентов за период." },
        { word: "Cookie", trans: "Небольшой фрагмент данных, который веб-сайт сохраняет в браузере пользователя для запоминания настроек, авторизации или отслеживания поведения." },
        { word: "ROI", trans: "Return on Investment — рентабельность инвестиций. Показатель эффективности вложений: (прибыль − затраты) / затраты × 100%." },
        { word: "RR", trans: "Retention Rate — коэффициент удержания. Доля клиентов, продолживших пользоваться продуктом или услугой за определённый период." },
        { word: "SMM-продвижение", trans: "Social Media Marketing — продвижение бренда, продукта или услуги через социальные сети (контент, таргет, работа с блогерами)." },
        { word: "UTM-метка", trans: "Urchin Tracking Module — фрагмент URL-адреса, добавляемый к ссылке для отслеживания источника трафика в системах аналитики." },
        { word: "UX-дизайн", trans: "User Experience design — проектирование пользовательского опыта. Создание удобных, понятных и приятных интерфейсов продуктов." },
        { word: "XYZ-анализ", trans: "Метод классификации по стабильности спроса: X (стабильный спрос), Y (колеблющийся), Z (нерегулярный, трудно прогнозируемый)." },
        { word: "Апсейл", trans: "Upsell — техника продаж, при которой клиенту предлагают более дорогую версию товара или дополнительную услугу для увеличения среднего чека." },
        { word: "Арбитраж трафика", trans: "Покупка трафика на одних площадках по низкой цене и перенаправление его на другие (офферы) с целью заработка на разнице." },
        { word: "Бенчмаркинг", trans: "Процесс сравнения своих бизнес-процессов и показателей с лучшими практиками конкурентов или лидеров рынка для поиска точек роста." },
        { word: "Вирусная реклама", trans: "Рекламный контент, который пользователи добровольно и активно распространяют сами (через репосты, пересылки) благодаря высокой эмоциональности или полезности." },
        { word: "Геймификация", trans: "Использование игровых механик (очки, уровни, рейтинги, награды) в неигровых процессах для повышения вовлечённости пользователей или сотрудников." },
        { word: "Директ-маркетинг", trans: "Прямой маркетинг — коммуникация с целевой аудиторией без посредников (email-рассылки, SMS, телемаркетинг) с измеримым откликом." },
        { word: "Дистрибуция", trans: "Процесс распределения и доставки товара от производителя к конечному потребителю через сеть посредников (дистрибьюторов, дилеров, розницу)." },
        { word: "Дифференцированный маркетинг", trans: "Стратегия, при которой компания разрабатывает отдельные продукты и маркетинговые программы для разных сегментов рынка." },
        { word: "Кастомизация", trans: "Адаптация продукта или услуги под индивидуальные запросы конкретного клиента (персонализация, кастомный дизайн)." },
        { word: "Категорийный менеджмент", trans: "Управление ассортиментом товарной категории как отдельным бизнесом: анализ, планирование, ценообразование, промо для максимизации прибыли категории." },
        { word: "Клиентоориентированность", trans: "Философия бизнеса, ставящая интересы и потребности клиента в центр всех процессов компании." },
        { word: "Клиентский опыт", trans: "Customer Experience (CX) — совокупность всех впечатлений и эмоций клиента от взаимодействия с брендом на всех этапах." },
        { word: "Ключевые слова", trans: "Слова и фразы, которые пользователи вводят в поисковую систему; используются в SEO и контекстной рекламе для привлечения целевого трафика." },
        { word: "Конверсия", trans: "Отношение числа пользователей, выполнивших целевое действие (покупку, заявку), к общему числу посетителей, выраженное в процентах." },
        { word: "Контекстная реклама", trans: "Рекламные объявления, показываемые пользователю в соответствии с содержанием просматриваемой им страницы или его поисковым запросом." },
        { word: "Лид", trans: "Потенциальный клиент, проявивший интерес к продукту и оставивший свои контактные данные (заявка, подписка, звонок)." },
        { word: "Маркетинг", trans: "Деятельность по изучению рынка, выявлению потребностей клиентов и удовлетворению их с целью получения прибыли." },
        { word: "Маркетинг-микс", trans: "Комплекс маркетинга (4P): Product (продукт), Price (цена), Place (место/дистрибуция), Promotion (продвижение)." },
        { word: "Маркетинговая стратегия", trans: "Долгосрочный план достижения маркетинговых целей компании: выбор целевых сегментов, позиционирования и комплекса инструментов." },
        { word: "Маркетинговый анализ", trans: "Исследование рынка, конкурентов, потребителей и внутренней среды компании для принятия обоснованных маркетинговых решений." },
        { word: "Маркировка «Честный знак»", trans: "Национальная система цифровой маркировки товаров в РФ. Каждый товар получает уникальный Data Matrix код для отслеживания от производства до продажи." },
        { word: "Медиаплан", trans: "Документ, описывающий стратегию размещения рекламы: каналы, сроки, бюджеты, ожидаемые показатели охвата и частоты." },
        { word: "Медийная реклама", trans: "Реклама в виде баннеров, видео, аудио на сайтах, в приложениях и соцсетях, направленная на формирование имиджа и охват аудитории." },
        { word: "Нативная реклама", trans: "Рекламный контент, стилизованный под обычный editorial-материал площадки (статья, пост), чтобы ненавязчиво интегрироваться в ленту пользователя." },
        { word: "Неценовая конкуренция", trans: "Соперничество компаний за счёт качества, сервиса, бренда, инноваций, а не за счёт снижения цены." },
        { word: "Ниша", trans: "Узкий сегмент рынка с специфическими потребностями, где конкуренция ниже, а компания может занять лидирующую позицию." },
        { word: "Партизанский маркетинг", trans: "Нестандартные, малобюджетные способы продвижения, основанные на креативе и эффекте неожиданности (флешмобы, стикеры, граффити)." },
        { word: "Позиционирование", trans: "Формирование в сознании целевой аудитории уникального образа бренда или продукта, отличающего его от конкурентов." },
        { word: "Потребительская корзина", trans: "Набор товаров и услуг, необходимый для удовлетворения первоочередных потребностей человека или семьи за определённый период." },
        { word: "Потребительское поведение", trans: "Совокупность действий и решений потребителей, связанных с поиском, выбором, покупкой и использованием товаров и услуг." },
        { word: "Пресейл", trans: "Presale — предпродажная подготовка: технические консультации, демонстрации, подготовка коммерческих предложений для сложных B2B-продаж." },
        { word: "Программа лояльности", trans: "Система поощрения постоянных клиентов (бонусы, скидки, накопительные карты) для увеличения повторных покупок." },
        { word: "Ребрендинг", trans: "Комплексное изменение бренда: названия, логотипа, фирменного стиля, позиционирования для обновления имиджа или выхода на новые рынки." },
        { word: "Рекламация", trans: "Письменная претензия покупателя к продавцу по поводу недостатков товара, нарушения сроков или условий договора." },
        { word: "Ремаркетинг", trans: "Повторный показ рекламы пользователям, которые уже посещали сайт или взаимодействовали с брендом, но не совершили целевое действие." },
        { word: "Ретейл", trans: "Retail — розничная торговля; продажа товаров и услуг конечным потребителям для личного использования." },
        { word: "Таргет", trans: "Targeted advertising — таргетированная реклама в социальных сетях, показываемая строго определённой аудитории по заданным параметрам (возраст, интересы, гео)." },
        { word: "Товаровед", trans: "Специалист, занимающийся изучением потребительских свойств товаров, контролем их качества, классификацией и экспертизой." },
        { word: "Торговля розничная", trans: "Деятельность по продаже товаров непосредственно конечным потребителям для личных, семейных или домашних нужд." },
        { word: "Тренд", trans: "Устойчивая тенденция изменения рынка, потребительских предпочтений или технологий, сохраняющаяся в течение длительного времени." },
        { word: "Трейд-маркетинг", trans: "Комплекс мероприятий, направленных на стимулирование продаж через торговые сети и точки продаж (мерчандайзинг, промо для ритейла)." }
    ],

    topic2: [
        { word: "Актив", trans: "Ресурс, контролируемый компанией в результате прошлых событий, от которого ожидается получение экономических выгод в будущем (деньги, оборудование, дебиторская задолженность)." },
        { word: "Амортизация", trans: "Процесс постепенного переноса стоимости основных средств и нематериальных активов на себестоимость продукции по мере их износа." },
        { word: "Бухгалтерский баланс", trans: "Финансовый отчёт, отражающий состояние активов, обязательств и капитала компании на определённую дату. Активы всегда равны пассивам (капитал + обязательства)." },
        { word: "Бухгалтерский учет", trans: "Упорядоченная система сбора, регистрации и обобщения информации в денежном выражении об имуществе, обязательствах и хозяйственных операциях." },
        { word: "Валовая прибыль", trans: "Разница между выручкой от реализации и себестоимостью проданных товаров или услуг. Показывает эффективность основного бизнеса до вычета прочих расходов." },
        { word: "ВВП", trans: "Валовой внутренний продукт — рыночная стоимость всех конечных товаров и услуг, произведённых на территории страны за год." },
        { word: "Внеоборотные активы", trans: "Активы, используемые в деятельности компании более 12 месяцев (основные средства, нематериальные активы, долгосрочные финансовые вложения)." },
        { word: "Волатильность", trans: "Степень изменчивости цены финансового инструмента или рынка за определённый период. Высокая волатильность означает высокие риски и возможности." },
        { word: "Выписка из бухгалтерского баланса", trans: "Документ, содержащий сведения об активах, обязательствах и капитале компании на определённую дату; используется для подтверждения финансового состояния." },
        { word: "Дебиторская задолженность", trans: "Сумма долгов, причитающихся компании от физических или юридических лиц (покупателей, заказчиков) в результате хозяйственных отношений." },
        { word: "ДДС", trans: "Движение денежных средств (Cash Flow) — отчёт, показывающий все поступления и выплаты денег компании за период, разделённые на операционную, инвестиционную и финансовую деятельность." },
        { word: "Девальвация", trans: "Официальное снижение курса национальной валюты по отношению к иностранным валютам, проводимое центральным банком." },
        { word: "Денежная эмиссия", trans: "Выпуск в обращение наличных или безналичных денег центральным банком, увеличивающий общую денежную массу в экономике." },
        { word: "Денежно-кредитная политика", trans: "Совокупность мер центрального банка по регулированию денежной массы, процентных ставок и инфляции для обеспечения стабильности экономики." },
        { word: "Денежный поток", trans: "Поступление или выбытие денежных средств и их эквивалентов в результате хозяйственной деятельности компании." },
        { word: "Деноминация", trans: "Укрупнение национальной денежной единицы путём обмена старых денег на новые в определённом соотношении (например, 1000:1) без изменения покупательной способности." },
        { word: "Депозит", trans: "Денежные средства, переданные банку во временное пользование на определённый срок под процент для сохранения и приумножения." },
        { word: "Дефляция", trans: "Устойчивое снижение общего уровня цен на товары и услуги в экономике; противоположность инфляции." },
        { word: "Дефолт", trans: "Невыполнение заёмщиком (государством или компанией) своих обязательств по выплате долга или процентов по нему." },
        { word: "Дивиденды", trans: "Часть чистой прибыли акционерного общества, распределяемая между акционерами пропорционально количеству принадлежащих им акций." },
        { word: "Добавочный капитал", trans: "Часть собственного капитала компании, образующаяся за счёт эмисионного дохода (превышение цены размещения акций над номиналом), переоценки активов и др." },
        { word: "Доход", trans: "Экономическая выгода в денежной или натуральной форме, полученная в результате деятельности или владения имуществом." },
        { word: "Задаток", trans: "Денежная сумма, выдаваемая одной стороной другой в счёт будущих платежей как доказательство заключения договора и в обеспечение его исполнения." },
        { word: "Заем", trans: "Передача денег или вещей в собственность другой стороне с условием возврата такого же количества денег или вещей того же рода и качества." },
        { word: "Издержки", trans: "Денежные затраты компании на приобретение ресурсов, необходимых для производства и реализации продукции." },
        { word: "Инвестиции", trans: "Вложение капитала в объекты предпринимательской деятельности с целью получения прибыли или достижения иного полезного эффекта." },
        { word: "Инфляция", trans: "Устойчивый рост общего уровня цен на товары и услуги, приводящий к снижению покупательной способности денег." },
        { word: "Капитал", trans: "Стоимость, приносящая прибавочную стоимость; совокупность финансовых, материальных и интеллектуальных ресурсов, используемых для получения дохода." },
        { word: "Капитализация", trans: "Рыночная стоимость компании, рассчитываемая как произведение текущей цены одной акции на общее количество выпущенных акций." },
        { word: "Кассационная жалоба", trans: "Жалоба на вступившие в законную силу судебные решения, подаваемая в кассационный суд с целью проверки законности этих решений." },
        { word: "КБК", trans: "Код бюджетной классификации — цифровой код, указываемый в платёжном поручении для правильного зачисления налога или платежа в соответствующий бюджет." },
        { word: "Коммерческие расходы", trans: "Затраты, связанные со сбытом продукции: реклама, упаковка, доставка, зарплата торгового персонала, аренда торговых помещений." },
        { word: "Кредит", trans: "Предоставление денег или товаров в долг, обычно с условием возврата в определённый срок и уплаты процентов." },
        { word: "Курс валюты", trans: "Цена денежной единицы одной страны, выраженная в денежных единицах другой страны или в международной валютной единице." },
        { word: "Личный кабинет налогоплательщика", trans: "Онлайн-сервис Федеральной налоговой службы, позволяющий физическим лицам и ИП контролировать начисления, платить налоги и подавать декларации дистанционно." },
        { word: "Маржинальная торговля", trans: "Торговля с использованием кредитного плеча: трейдер вносит часть средств (маржу), а брокер предоставляет остальное для увеличения объёма сделки." },
        { word: "МВФ", trans: "Международный валютный фонд — международная организация, содействующая стабильности валютных курсов, предоставляющая кредиты странам с проблемами платёжного баланса." },
        { word: "Накладная", trans: "Первичный документ, сопровождающий груз и подтверждающий факт его отгрузки и передачи от продавца к покупателю." },
        { word: "Накладные расходы", trans: "Общехозяйственные и общепроизводственные затраты, которые нельзя напрямую отнести на себестоимость конкретного изделия (аренда офиса, зарплата администрации)." },
        { word: "Налог", trans: "Обязательный, индивидуально безвозмездный платёж, взимаемый с организаций и физических лиц государством для финансирования его деятельности." },
        { word: "Налоговая инспекция", trans: "Территориальный орган Федеральной налоговой службы, осуществляющий контроль за правильностью исчисления и своевременностью уплаты налогов." },
        { word: "Налоговый вычет", trans: "Сумма, на которую уменьшается налогооблагаемый доход физического лица (например, при покупке жилья, лечении, обучении), что снижает сумму НДФЛ к уплате." },
        { word: "Налоговый кодекс", trans: "Основной законодательный акт РФ, регулирующий отношения по установлению, введению и взиманию налогов и сборов." },
        { word: "Наложенный платеж", trans: "Способ оплаты товара при получении: покупатель оплачивает заказ курьеру или в пункте выдачи в момент доставки." },
        { word: "НДФЛ", trans: "Налог на доходы физических лиц — прямой налог, взимаемый с доходов граждан (зарплата, продажа имущества, дивиденды). Основная ставка в РФ — 13%." },
        { word: "Незавершенное производство", trans: "Продукция, не прошедшая всех стадий обработки и не готовая к реализации; учитывается как часть оборотных активов компании." },
        { word: "Нематериальные активы", trans: "Активы, не имеющие физической формы, но приносящие экономическую выгоду (патенты, лицензии, программное обеспечение, товарные знаки)." },
        { word: "Номинал", trans: "Наречительная стоимость, указанная на ценной бумаге или денежном знаке; база для расчёта купонного дохода или дивидендов." },
        { word: "НПД", trans: "Налог на профессиональный доход — специальный налоговый режим для самозанятых граждан в РФ (ставки 4% при работе с физлицами, 6% — с юрлицами)." },
        { word: "Оборот", trans: "Общий объём продаж товаров или услуг компании за определённый период, выраженный в денежной форме (выручка)." },
        { word: "Облигации", trans: "Долговые ценные бумаги, удостоверяющие право владельца на получение от эмитента номинальной стоимости и фиксированного процента (купона) в установленные сроки." },
        { word: "Овердрафт", trans: "Краткосрочный кредит, предоставляемый банком при недостатке средств на расчётном счёте клиента для покрытия текущих платежей." },
        { word: "Овернайт", trans: "Однодневная межбанковская ставка, по которой банки кредитуют друг друга на ночь для поддержания ликвидности." },
        { word: "Оклад", trans: "Фиксированная часть заработной платы работника, устанавливаемая тарифной сеткой или трудовым договором, без учёта премий и надбавок." },
        { word: "Основные средства", trans: "Материальные активы, используемые в производстве или управлении более 12 месяцев и стоимостью выше установленного лимита (здания, станки, транспорт)." },
        { word: "Отложенные налоговые активы", trans: "Часть отложенного налога на прибыль, которая должна привести к уменьшению налога, подлежащего уплате в бюджет в следующих отчётных периодах." },
        { word: "Отложенные налоговые обязательства", trans: "Часть отложенного налога на прибыль, которая должна привести к увеличению налога, подлежащего уплате в бюджет в следующих отчётных периодах." },
        { word: "Паевой фонд", trans: "Совокупность паёв, внесённых участниками кооператива или паевого инвестиционного фонда, используемая для совместной деятельности или инвестирования." },
        { word: "Пай", trans: "Имущественный взнос члена кооператива, дающий право на участие в управлении и получение части прибыли; также единица участия в ПИФе." },
        { word: "Паушальный взнос", trans: "Единовременный фиксированный платёж, взимаемый франчайзером с франчайзи за право пользования брендом и бизнес-моделью при заключении договора франшизы." },
        { word: "Пени", trans: "Денежная сумма, начисляемая за каждый день просрочки исполнения денежного обязательства; вид неустойки." },
        { word: "Платежное поручение", trans: "Распоряжение владельца счёта банку перевести определённую сумму денег на счёт получателя." },
        { word: "Порог рентабельности", trans: "Точка безубыточности — объём продаж, при котором выручка полностью покрывает все затраты (постоянные и переменные), и прибыль равна нулю." },
        { word: "Потребительский кредит", trans: "Кредит, предоставляемый физическому лицу для приобретения товаров, работ или услуг для личных нужд." },
        { word: "Прибыль", trans: "Финансовый результат деятельности компании: разница между доходами и расходами за определённый период." },
        { word: "Пролонгация вклада", trans: "Автоматическое или по заявлению продление срока банковского вклада на новый период после окончания предыдущего." },
        { word: "Процентная ставка", trans: "Цена кредита, выраженная в процентах от суммы долга за определённый период времени (год, месяц)." },
        { word: "Расписка", trans: "Письменный документ, удостоверяющий получение денег или вещей и обязательство вернуть их в определённый срок." },
        { word: "Рассрочка", trans: "Способ оплаты товара или услуги, при котором полная сумма выплачивается частями в течение определённого периода без начисления процентов (в отличие от кредита)." },
        { word: "Расчетный счет", trans: "Банковский счёт, открываемый юридическим лицам и ИП для проведения безналичных расчётов по хозяйственным операциям." },
        { word: "Рентабельность", trans: "Относительный показатель экономической эффективности, показывающий, сколько прибыли приходится на единицу затраченных ресурсов (активов, капитала, выручки)." },
        { word: "Рефинансирование", trans: "Получение нового кредита для погашения существующих долгов, обычно на более выгодных условиях (снижение ставки, увеличение срока)." },
        { word: "Роялти", trans: "Периодические платежи лицензиару (правообладателю) за право использования интеллектуальной собственности (патента, бренда, технологии), часто в % от выручки." },
        { word: "Сальдо", trans: "Разность между дебетовым и кредитовым оборотами по счёту; остаток средств на счёте на определённую дату." },
        { word: "Себестоимость", trans: "Совокупность всех затрат компании на производство и реализацию продукции, выраженная в денежной форме." },
        { word: "Сертификат соответствия", trans: "Документ, удостоверяющий, что продукция соответствует требованиям технических регламентов, стандартов или условий договора." },
        { word: "Спрос", trans: "Количество товара или услуги, которое покупатели готовы и способны приобрести по определённой цене за определённый период." },
        { word: "Стагнация", trans: "Застой в экономике, характеризующийся отсутствием роста ВВП, высоким уровнем безработицы и низкой инвестиционной активностью." },
        { word: "Стагфляция", trans: "Сочетание стагнации (спада производства) и высокой инфляции; редкое и опасное состояние экономики." },
        { word: "Страховая компания", trans: "Организация, осуществляющая страхование: принимает страховые премии и выплачивает возмещение при наступлении страховых случаев." },
        { word: "Счет-эскроу", trans: "Специальный банковский счёт, на котором блокируются деньги покупателя до выполнения продавцом условий сделки (используется в сделках с недвижимостью)." },
        { word: "Транш", trans: "Часть общей суммы кредита или займа, выдаваемая заёмщику в определённый срок согласно графику." },
        { word: "Фонд оплаты труда", trans: "Совокупность всех выплат работникам компании за определённый период (оклады, премии, надбавки, компенсации)." },
        { word: "Фондоотдача", trans: "Показатель эффективности использования основных средств: отношение выручки к среднегодовой стоимости основных фондов." },
        { word: "Эмитент", trans: "Организация или государство, выпускающие ценные бумаги (акции, облигации) или денежные знаки в обращение." },
        { word: "ЭСФ", trans: "Электронный счёт-фактура — цифровой аналог бумажного счёта-фактуры, формируемый и передаваемый через оператора ЭДО; обязателен для НДС-плательщиков в РФ." }
    ],

    topic3: [
        { word: "Аккредитация", trans: "Официальное признание компетентности организации или специалиста в определённой области органом по аккредитации." },
        { word: "Аккредитив", trans: "Банковская форма расчётов, при которой банк покупателя гарантирует оплату продавцу при предоставлении документов, подтверждающих отгрузку товара." },
        { word: "Акцепт", trans: "Согласие на оплату расчётного документа (счёта, векселя) или принятие оферты, влекущее заключение договора." },
        { word: "Акциз", trans: "Косвенный налог, включаемый в цену отдельных видов товаров (алкоголь, табак, топливо, автомобили) и уплачиваемый производителем или импортёром." },
        { word: "Акционерное общество", trans: "Коммерческая организация, уставный капитал которой разделён на акции; акционеры не отвечают по обязательствам АО и несут риск убытков в пределах стоимости акций." },
        { word: "Акции", trans: "Эмиссионные ценные бумаги, закрепляющие право владельца (акционера) на получение части прибыли (дивидендов), участие в управлении и часть имущества при ликвидации." },
        { word: "Альтернативная стоимость", trans: "Ценность наилучшей из упущенных возможностей; то, чем жертвует субъект, выбирая один вариант вместо другого." },
        { word: "Андеррайтинг", trans: "Процедура оценки рисков и определения условий выпуска ценных бумаг; андеррайтер берёт на себя обязательства по размещению выпуска." },
        { word: "АНО", trans: "Автономная некоммерческая организация — не имеющая членства НКО, учреждённая для предоставления услуг в сфере образования, здравоохранения, культуры и др." },
        { word: "Апостиль", trans: "Специальный штамп, проставляемый на официальном документе для его использования в странах — участницах Гаагской конвенции без дополнительной легализации." },
        { word: "Арбитр", trans: "Лицо, избранное сторонами для разрешения спора в третейском суде (арбитраже); выносит обязательное для сторон решение." },
        { word: "Арбитражный суд", trans: "Суд, рассматривающий экономические споры и дела, связанные с предпринимательской и иной экономической деятельностью." },
        { word: "Аудитор", trans: "Независимый специалист или фирма, проводящие проверку финансовой отчётности компании и выражающие мнение о её достоверности." },
        { word: "Аукцион", trans: "Публичная продажа товаров, ценных бумаг или имущества, при которой победителем становится участник, предложивший наивысшую цену." },
        { word: "Аутентификация", trans: "Процедура проверки подлинности пользователя, документа или объекта (например, ввод логина и пароля, сканирование отпечатка)." },
        { word: "Аутсорсинг", trans: "Передача непрофильных бизнес-функций (бухгалтерия, IT, клининг) внешней специализированной компании по договору." },
        { word: "Аутстаффинг", trans: "Вывод персонала из штата компании-заказчика в штат провайдера с последующим предоставлением этих сотрудников заказчику для выполнения работ." },
        { word: "Аффилированность", trans: "Способность одного лица оказывать влияние на предпринимательскую деятельность другого (через участие в капитале, родственные связи, договоры)." },
        { word: "Авторское право", trans: "Совокупность правовых норм, охраняющих права авторов на произведения науки, литературы и искусства; возникает с момента создания произведения." },
        { word: "Агрегаторы", trans: "Онлайн-платформы, собирающие предложения множества продавцов или поставщиков услуг в одном месте для удобства выбора покупателем (Яндекс.Маркет, Booking)." },
        { word: "Акселератор", trans: "Программа краткосрочной интенсивной поддержки стартапов: менторство, обучение, нетворкинг и часто посевные инвестиции в обмен на долю." },
        { word: "Байбэк", trans: "Buyback — обратный выкуп компанией собственных акций с рынка для сокращения их количества, повышения цены и EPS." },
        { word: "Бан", trans: "Блокировка учётной записи пользователя или доступа к ресурсу за нарушение правил платформы." },
        { word: "Банк", trans: "Финансовая организация, имеющая лицензию ЦБ на привлечение вкладов, размещение кредитов и проведение расчётов." },
        { word: "Банк России", trans: "Центральный банк Российской Федерации — мегарегулятор финансового рынка, отвечающий за денежно-кредитную политику, надзор за банками и эмиссию рубля." },
        { word: "Бартер", trans: "Прямой обмен товарами или услугами между сторонами без использования денег." },
        { word: "Бенефициар", trans: "Физическое лицо, которое в конечном счёте владеет компанией или получает выгоду от её деятельности, даже если формально собственником выступает другое лицо." },
        { word: "БИК банка", trans: "Банковский идентификационный код — уникальный номер, присваиваемый каждому подразделению Банка России и кредитной организации для идентификации в расчётах." },
        { word: "Биржа", trans: "Организованный рынок, на котором проводятся торги стандартизированными активами (акциями, облигациями, валютой, товарами) по установленным правилам." },
        { word: "Биржа труда", trans: "Государственное учреждение, содействующее занятости населения: регистрация безработных, подбор вакансий, профориентация, выплата пособий." },
        { word: "Больничный лист", trans: "Листок нетрудоспособности — документ, подтверждающий временную неспособность работника к труду и дающий право на пособие по болезни." },
        { word: "Боны", trans: "Разменные денежные знаки или купоны, выпускаемые временно в периоды дефицита наличности; также — бонусные баллы в программах лояльности." },
        { word: "БРИКС", trans: "Межгосударственное объединение Бразилии, России, Индии, Китая и ЮАР (с 2024 г. расширено), созданное для экономического и политического сотрудничества." },
        { word: "Бриф", trans: "Краткий документ, описывающий задачу, цели, целевую аудиторию и требования заказчика для исполнителя (дизайнера, рекламного агентства, разработчика)." },
        { word: "Вакансия", trans: "Свободная должность в организации, на которую ведётся поиск кандидата." },
        { word: "Валовой региональный продукт", trans: "Суммарная стоимость товаров и услуг, произведённых на территории региона за год; аналог ВВП на региональном уровне." },
        { word: "Валюта", trans: "Денежная единица, используемая в качестве меры стоимости и средства платежа в стране или группе стран." },
        { word: "Валютный контроль", trans: "Система мер государства по регулированию операций с иностранной валютой для предотвращения незаконного вывода капитала и обеспечения стабильности платёжного баланса." },
        { word: "Ваучер", trans: "Ценная бумага или документ, дающий право на получение товара, услуги или скидки; в 1990-х в РФ — приватизационный чек." },
        { word: "Вексель", trans: "Письменное долговое обязательство строго установленной формы, дающее его владельцу право требовать от должника уплаты определённой суммы в установленный срок." },
        { word: "Вендор", trans: "Поставщик оборудования, программного обеспечения или товаров, часто выступающий также как производитель или официальный дистрибьютор." },
        { word: "Верификация", trans: "Процесс подтверждения достоверности данных, личности пользователя или соответствия продукта требованиям (например, верификация аккаунта, верификация модели)." },
        { word: "Виджет", trans: "Небольшой интерактивный элемент интерфейса (на сайте или в ОС), выполняющий конкретную функцию (часы, погода, форма подписки)." },
        { word: "Виды экономической деятельности", trans: "Классификация хозяйственной деятельности организаций и ИП по ОКВЭД; определяет применяемые налоговые режимы, тарифы взносов и отчётность." },
        { word: "Вклад", trans: "Денежные средства, размещённые физическим или юридическим лицом в банке на определённый срок или до востребования под процент." },
        { word: "Возврат", trans: "Процедура возвращения товара покупателем продавцу с восстановлением уплаченных средств или заменой на другой товар." },
        { word: "Водяной знак", trans: "Полупрозрачное изображение или текст, накладываемый на цифровой контент (фото, документ) для защиты авторских прав или указания источника." },
        { word: "Гарант", trans: "Лицо или организация, принимающие на себя обязательство отвечать за исполнение другим лицом его обязательств перед кредитором." },
        { word: "Генеральный директор", trans: "Единоличный исполнительный орган компании, руководящий её текущей деятельностью и действующий от имени юридического лица без доверенности." },
        { word: "Глобализация", trans: "Процесс всемирной экономической, политической и культурной интеграции, ведущий к формированию единого мирового рынка." },
        { word: "Госзакупка", trans: "Закупка товаров, работ или услуг государственными или муниципальными заказчиками за счёт бюджетных средств в рамках 44-ФЗ или 223-ФЗ." },
        { word: "Грант", trans: "Безвозмездная субсидия, предоставляемая государством, фондом или организацией на конкурсной основе для реализации проекта в науке, образовании, культуре или бизнесе." },
        { word: "Грузовая таможенная декларация", trans: "Документ, подаваемый в таможенные органы при перемещении товаров через границу; содержит сведения о товаре, его стоимости, происхождении и целях ввоза/вывоза." },
        { word: "Декларация", trans: "Официальное заявление о доходах, имуществе, товарах или иных сведениях, подаваемое в государственный орган (налоговая декларация, таможенная декларация)." },
        { word: "Делистинг", trans: "Исключение ценных бумаг из списка допускаемых к торгам на бирже (противоположность листингу)." },
        { word: "Демпинг", trans: "Продажа товаров по искусственно заниженным ценам (часто ниже себестоимости) для вытеснения конкурентов и захвата рынка." },
        { word: "Дистрибьютор", trans: "Оптовый посредник, закупающий товары у производителя и реализующий их розничным продавцам или конечным потребителям на определённой территории." },
        { word: "Договор", trans: "Соглашение двух или нескольких лиц об установлении, изменении или прекращении гражданских прав и обязанностей." },
        { word: "Доля рынка", trans: "Часть общего объёма продаж на рынке, приходящаяся на конкретную компанию или бренд, выраженная в процентах или натуральных единицах." },
        { word: "Драйвер", trans: "Фактор, оказывающий решающее влияние на развитие процесса или показателя (драйвер роста выручки, драйвер стоимости)." },
        { word: "ДРР", trans: "Доля рекламных расходов — отношение затрат на рекламу к выручке, полученной от этой рекламы, выраженное в процентах. Ключевой показатель эффективности маркетинга." },
        { word: "ЕГРИП", trans: "Единый государственный реестр индивидуальных предпринимателей — федеральная база данных, содержащая сведения обо всех зарегистрированных в РФ ИП." },
        { word: "ЕГРЮЛ", trans: "Единый государственный реестр юридических лиц — федеральная база данных, содержащая сведения обо всех зарегистрированных в РФ юридических лицах." },
        { word: "ЕРИР", trans: "Единый реестр интернет-рекламы — государственная система учёта всей интернет-рекламы в РФ; все объявления должны быть промаркированы и переданы в ЕРИР." },
        { word: "ЕФРСБ", trans: "Единый федеральный реестр сведений о банкротстве — открытая база данных о процедурах банкротства юридических и физических лиц в РФ." },
        { word: "Жизненный цикл товара", trans: "Период существования товара на рынке от разработки и вывода до снятия с производства; включает этапы: внедрение, рост, зрелость, спад." },
        { word: "ЗАО", trans: "Закрытое акционерное общество — форма АО (устаревшее название, с 2014 г. — непубличное АО), акции которого распределяются только среди учредителей или заранее определённого круга лиц." },
        { word: "Залог", trans: "Способ обеспечения обязательства, при котором кредитор имеет право в случае неисполнения должником обязательства получить удовлетворение из стоимости заложенного имущества." },
        { word: "Заявление", trans: "Письменное обращение гражданина или организации в государственный орган или компанию с просьбой о совершении определённых действий или принятии решения." },
        { word: "Инкассация", trans: "Услуга банка по перевозке наличных денег и ценностей из торговых точек в банк с обеспечением безопасности." },
        { word: "Инсайдер", trans: "Лицо, имеющее доступ к конфиденциальной информации о компании (инсайдерской информации), использование которой для торговли ценными бумагами запрещено." },
        { word: "ИП", trans: "Индивидуальный предприниматель — физическое лицо, зарегистрированное в установленном порядке и осуществляющее предпринимательскую деятельность без образования юридического лица." },
        { word: "Испытательный срок", trans: "Период в начале трудовых отношений, устанавливаемый для проверки соответствия работника поручаемой работе (обычно до 3 месяцев)." },
        { word: "Итерация", trans: "Повторение цикла действий с целью приближения к желаемому результату; в agile — короткий рабочий цикл (спринт), по итогам которого создаётся инкремент продукта." },
        { word: "Кадастр", trans: "Систематизированный свод сведений о природных, экономических или юридических объектах (земельный кадастр, кадастр недвижимости)." },
        { word: "Кадастровая стоимость", trans: "Стоимость объекта недвижимости, определяемая методами массовой оценки для целей налогообложения; устанавливается государственными органами." },
        { word: "Казначейский счет", trans: "Счёт, открытый органу Федерального казначейства в Банке России для учёта операций со средствами бюджетов бюджетной системы РФ." },
        { word: "Казначейство", trans: "Федеральное казначейство — орган исполнительной власти, осуществляющий кассовое обслуживание исполнения бюджетов бюджетной системы РФ." },
        { word: "Калькуляция", trans: "Исчисление себестоимости единицы продукции, работы или услуги путём суммирования всех затрат, относящихся к данному объекту." },
        { word: "Кастодиальный кошелек", trans: "Криптокошелёк, ключи от которого хранятся у третьей стороны (биржи, сервиса); пользователь не контролирует приватные ключи напрямую." },
        { word: "Категории персонала", trans: "Группы работников, выделяемые по характеру труда: руководители, специалисты, служащие, рабочие." },
        { word: "Квиз", trans: "Интерактивная викторина или тест, используемый в маркетинге для вовлечения аудитории, сбора контактов или развлечения." },
        { word: "Киберпонедельник", trans: "День масштабных распродаж в интернет-магазинах, следующий за «Чёрной пятницей»; аналог в e-commerce." },
        { word: "Клиринг", trans: "Система безналичных расчётов между банками или участниками биржи, основанная на взаимном зачёте требований и обязательств." },
        { word: "Коворкинг", trans: "Общее офисное пространство, где независимые профессионалы, фрилансеры и стартапы арендуют рабочие места и пользуются общей инфраструктурой." },
        { word: "Колл-трекинг", trans: "Технология подмены номеров на сайте в зависимости от источника трафика для определения, с какой рекламы пришёл звонок." },
        { word: "Колл-центр", trans: "Подразделение или аутсорсинговая компания, обрабатывающая входящие и исходящие телефонные звонки клиентов (поддержка, продажи, опросы)." },
        { word: "Коллаборация", trans: "Совместный проект двух или более брендов, артистов или компаний для создания уникального продукта или усиления маркетингового эффекта." },
        { word: "Коммерческий директор", trans: "Руководитель, отвечающий за коммерческую деятельность компании: продажи, маркетинг, закупки, развитие клиентской базы и достижение финансовых целей." },
        { word: "Комплаенс", trans: "Система внутреннего контроля, обеспечивающая соответствие деятельности компании законодательству, отраслевым стандартам и внутренним политикам." },
        { word: "Комплекс маркетинга", trans: "Совокупность управляемых параметров маркетинговой деятельности (4P: продукт, цена, место, продвижение), комбинируя которые компания достигает своих целей на рынке." },
        { word: "Консалтинг", trans: "Предоставление экспертных консультаций и рекомендаций компаниям по вопросам стратегии, управления, финансов, IT и других областей." },
        { word: "Консорциум", trans: "Временное объединение независимых компаний для совместной реализации крупного проекта, требующего объединения ресурсов и компетенций." },
        { word: "Контрагент", trans: "Одна из сторон договора; организация или ИП, с которыми компания состоит в хозяйственных отношениях (поставщик, покупатель, подрядчик)." },
        { word: "Контракт", trans: "Письменный договор, часто используемый во внешнеэкономической деятельности или при закупках; фиксирует условия поставки, оплаты и ответственности сторон." },
        { word: "Концерна", trans: "Концерн — форма объединения предприятий, связанных производственными и финансовыми интересами вокруг головной компании; участники сохраняют юридическую самостоятельность." },
        { word: "Концессия", trans: "Договор, по которому государство передаёт частной компании право на эксплуатацию объектов инфраструктуры или природных ресурсов на определённый срок за плату." },
        { word: "Корнер", trans: "Небольшая торговая точка или островок в торговом центре, специализирующаяся на узком ассортименте (кофе, аксессуары, косметика)." },
        { word: "Котировки", trans: "Цены, по которым готовы купить (bid) или продать (ask) ценную бумагу, валюту или товар на бирже в данный момент." },
        { word: "Коуч", trans: "Специалист, помогающий клиенту достичь личных или профессиональных целей через серию вопросов, раскрытие потенциала и построение плана действий." },
        { word: "КПП", trans: "Код причины постановки на учёт — девятизначный код, присваиваемый налоговым органом каждой организации по месту её нахождения или ведения деятельности." },
        { word: "Криптовалюта", trans: "Цифровая валюта, функционирующая на базе технологии блокчейн без центрального эмитента; используется как средство обмена или инвестиционный актив." },
        { word: "Кросс-докинг", trans: "Система логистики, при которой товар проходит через склад без длительного хранения: принимается, сортируется и сразу отгружается дальше." },
        { word: "КРТ", trans: "Комплексное развитие территории — механизм градостроительной политики, предполагающий реновацию кварталов с ветхим жильём и создание новой инфраструктуры." },
        { word: "Кэш", trans: "Наличные деньги; также — кэшбэк (возврат части потраченных средств) или кэширование (временное хранение данных для ускорения доступа)." },
        { word: "Лендинг", trans: "Landing page — одностраничный сайт, созданный для конвертации посетителя в лида или покупателя; фокусируется на одном предложении и призыве к действию." },
        { word: "Лизинг", trans: "Финансовая аренда: лизинговая компания приобретает имущество по выбору клиента и передаёт ему во временное пользование за плату с правом последующего выкупа." },
        { word: "Ликвидация", trans: "Процедура прекращения деятельности юридического лица без перехода прав и обязанностей к другим лицам; включает расчёты с кредиторами и распределение оставшегося имущества." },
        { word: "Ликвидность", trans: "Способность актива быть быстро проданным по рыночной цене без существенной потери стоимости; также — способность компании своевременно погашать обязательства." },
        { word: "Листинг", trans: "Процедура допуска ценных бумаг к торгам на бирже после проверки эмитента на соответствие требованиям биржи." },
        { word: "Логистика", trans: "Наука и практика управления потоками товаров, информации и финансов от производителя к потребителю с минимальными затратами и в оптимальные сроки." },
        { word: "Логотип", trans: "Графический символ или стилизованное название, служащее для визуальной идентификации бренда или компании." },
        { word: "Локальный нормативный акт", trans: "Внутренний документ организации (правила внутреннего трудового распорядка, положение об оплате труда), регулирующий отношения в рамках этой организации." },
        { word: "ЛПР", trans: "Лицо, принимающее решение — ключевой человек в компании-клиенте, от которого зависит заключение сделки (в B2B-продажах)." },
        { word: "Менеджер", trans: "Специалист, осуществляющий управление определённым направлением, проектом или командой в организации." },
        { word: "Монополия", trans: "Рыночная структура, при которой одна компания контролирует весь или почти весь рынок определённого товара, диктуя цены и условия." },
        { word: "Накопительный счет", trans: "Банковский счёт, на который можно свободно вносить и снимать средства, получая процент на остаток; более гибкий, чем срочный вклад." },
        { word: "Национальный режим", trans: "Принцип, согласно которому иностранным товарам и поставщикам предоставляются те же условия, что и отечественным, в рамках госзакупок и торговли." },
        { word: "Неликвид", trans: "Товар или актив, который невозможно или крайне сложно продать по рыночной цене в разумные сроки." },
        { word: "НКО", trans: "Некоммерческая организация — организация, не имеющая извлечение прибыли в качестве основной цели и не распределяющая полученную прибыль между участниками." },
        { word: "Нормативный правовой акт", trans: "Официальный документ, принятый уполномоченным органом государственной власти, содержащий правовые нормы, обязательные для неопределённого круга лиц." },
        { word: "Нормирование труда", trans: "Установление мер труда (норм времени, выработки, обслуживания) для рационального использования рабочего времени и оценки производительности." },
        { word: "Нотариус", trans: "Лицо, уполномоченное совершать нотариальные действия (удостоверять сделки, завещания, копии документов) для придания им юридической силы." },
        { word: "ОАО", trans: "Открытое акционерное общество — форма АО (устаревшее название, с 2014 г. — публичное АО), акции которого могут свободно обращаться на рынке." },
        { word: "Облачное хранилище", trans: "Сервис удалённого хранения данных на серверах провайдера с доступом через интернет (Google Drive, Яндекс.Диск, Dropbox)." },
        { word: "Обособленное подразделение", trans: "Территориально обособленная часть организации (филиал, представительство, офис), оборудованная рабочими местами на срок более 1 месяца." },
        { word: "ОГРН", trans: "Основной государственный регистрационный номер — уникальный идентификатор юридического лица, присваиваемый при регистрации в ЕГРЮЛ." },
        { word: "ОГРНИП", trans: "Основной государственный регистрационный номер индивидуального предпринимателя — уникальный идентификатор ИП, присваиваемый при регистрации в ЕГРИП." },
        { word: "ОКВЭД", trans: "Общероссийский классификатор видов экономической деятельности — справочник кодов, используемый для классификации деятельности организаций и ИП при регистрации." },
        { word: "Олигополия", trans: "Рыночная структура, при которой несколько крупных компаний контролируют большую часть рынка и могут влиять на цены и условия." },
        { word: "Онбординг", trans: "Процесс адаптации нового сотрудника или пользователя продукта: обучение, знакомство с правилами, помощь в первых шагах для быстрого выхода на продуктивность." },
        { word: "ООО", trans: "Общество с ограниченной ответственностью — коммерческая организация, уставный капитал которой разделён на доли; участники не отвечают по обязательствам ООО сверх своей доли." },
        { word: "Операционная система", trans: "Комплекс программ, управляющих ресурсами компьютера и обеспечивающих взаимодействие пользователя с аппаратным обеспечением (Windows, macOS, Linux, Android)." },
        { word: "Оптимизация бизнес-процессов", trans: "Анализ и улучшение рабочих процессов компании для повышения эффективности, снижения затрат и устранения потерь." },
        { word: "Опцион", trans: "Производный финансовый инструмент, дающий право (но не обязанность) купить или продать базовый актив по заранее определённой цене в будущем." },
        { word: "Организационная структура предприятия", trans: "Схема соподчинения подразделений, должностей и функций в компании, определяющая иерархию и распределение ответственности." },
        { word: "Организационно-правовая форма", trans: "Законодательно закреплённая форма организации бизнеса (ООО, АО, ИП, кооператив и др.), определяющая порядок регистрации, управления, ответственности и налогообложения." },
        { word: "Ордер", trans: "Распоряжение на совершение операции (биржевой ордер на покупку/продажу) или документ, дающий право на занятие жилого помещения (ордер на квартиру)." },
        { word: "ОСНО", trans: "Общая система налогообложения — налоговый режим, при котором организация или ИП уплачивает НДС, налог на прибыль (или НДФЛ) и налог на имущество." },
        { word: "Отдел кадров", trans: "Подразделение компании, отвечающее за подбор, оформление, учёт, развитие и увольнение персонала, а также ведение кадровой документации." },
        { word: "Отпуск", trans: "Ежегодный оплачиваемый перерыв в работе, предоставляемый работнику для отдыха и восстановления трудоспособности (минимум 28 календарных дней в РФ)." },
        { word: "Отчет", trans: "Документ, содержащий сведения о результатах деятельности, исполнении бюджета, финансовых показателях или проделанной работе за определённый период." },
        { word: "Оферта", trans: "Предложение заключить договор, содержащее все существенные условия; акцепт оферты означает согласие и заключение договора." },
        { word: "ОФЗ", trans: "Облигации федерального займа — государственные ценные бумаги РФ, выпускаемые Минфином для финансирования дефицита бюджета; считаются надёжным инструментом." },
        { word: "Охват", trans: "Reach — количество уникальных пользователей, увидевших рекламное сообщение или контент за определённый период." },
        { word: "Охрана труда", trans: "Система сохранения жизни и здоровья работников в процессе трудовой деятельности, включающая правовые, социально-экономические, санитарно-гигиенические и лечебно-профилактические мероприятия." },
        { word: "Патент на изобретение", trans: "Охранный документ, удостоверяющий приоритет, авторство и исключительное право на использование технического решения, признанного изобретением." },
        { word: "Пенсионный возраст", trans: "Возраст, по достижении которого гражданин приобретает право на страховую пенсию по старости (в РФ: 60 лет для женщин, 65 лет для мужчин после реформы)." },
        { word: "Переводной вексель", trans: "Тратта — письменное приказание векселедателя плательщику уплатить определённую сумму третьему лицу (ремитенту) в установленный срок." },
        { word: "Платежная система", trans: "Совокупность правил, процедур и технической инфраструктуры для перевода денежных средств между участниками (Visa, Mastercard, МИР, PayPal)." },
        { word: "Поведенческие факторы", trans: "Параметры взаимодействия пользователя с сайтом (время на сайте, глубина просмотра, клики), используемые поисковыми системами для ранжирования." },
        { word: "Повышение квалификации", trans: "Обучение работников с целью обновления и расширения их профессиональных знаний и навыков в соответствии с требованиями должности." },
        { word: "Полевое исследование", trans: "Сбор первичных данных непосредственно в среде потребления или продаж (наблюдение, опросы, эксперименты в магазинах, на улицах)." },
        { word: "Политика конфиденциальности", trans: "Документ, описывающий, какие персональные данные собирает сайт или приложение, как они обрабатываются, хранятся и защищаются." },
        { word: "Посредник", trans: "Лицо или организация, содействующие заключению сделки между продавцом и покупателем, не являясь стороной самой сделки (агент, брокер, дилер)." },
        { word: "Пояснительная записка", trans: "Документ, сопровождающий финансовую отчётность или проект, содержащий разъяснения, детализацию показателей и описание методологии." },
        { word: "Предпринимательские риски", trans: "Вероятность возникновения убытков или недополучения доходов в результате непредвиденных изменений условий ведения бизнеса." },
        { word: "Производственный календарь", trans: "Официальный документ, определяющий нормы рабочего времени, выходные и праздничные дни на год; используется для расчёта зарплаты и графиков." },
        { word: "Производственный кооператив", trans: "Коммерческая организация, созданная для совместной производственной деятельности на основе личного трудового участия членов и объединения их имущественных паев." },
        { word: "Прокси-сервер", trans: "Промежуточный сервер, через который проходят запросы клиента к интернет-ресурсам; используется для анонимности, кэширования или обхода ограничений." },
        { word: "Прокуратура", trans: "Единая федеральная система органов, осуществляющих надзор за соблюдением Конституции и исполнением законов на территории РФ." },
        { word: "Профайлер", trans: "Специалист или система, анализирующая поведение, транзакции или цифровой след пользователя для выявления мошенничества или составления профиля." },
        { word: "Протекционизм", trans: "Экономическая политика государства, направленная на защиту внутренних производителей от иностранной конкуренции через пошлины, квоты и субсидии." },
        { word: "Публичный сервитут", trans: "Право ограниченного пользования чужим земельным участком, устанавливаемое в общественных интересах (проход, прокладка коммуникаций) без изъятия участка." },
        { word: "РЕПО", trans: "Repurchase agreement — сделка, при которой одна сторона продаёт ценные бумаги другой с обязательством выкупить их обратно через определённый срок по заранее оговорённой цене." },
        { word: "Реорганизация", trans: "Процедура изменения организационно-правовой формы или структуры юридического лица (слияние, присоединение, разделение, выделение, преобразование) с правопреемством." },
        { word: "Референдум", trans: "Всенародное голосование граждан по важнейшим вопросам государственного или местного значения, результаты которого имеют юридическую силу." },
        { word: "Рецессия", trans: "Спад экономической активности, характеризующийся снижением ВВП, производства, занятости и доходов в течение как минимум двух кварталов подряд." },
        { word: "РКО", trans: "Расчётно-кассовое обслуживание — комплекс банковских услуг по ведению расчётного счёта: приём и перевод платежей, кассовые операции, выписки." },
        { word: "РНП", trans: "Реестр недобросовестных поставщиков — список компаний и ИП, нарушивших условия госконтрактов; попадание в РНП запрещает участие в госзакупках на 2 года." },
        { word: "Росфинмониторинг", trans: "Федеральная служба по финансовому мониторингу — орган, противодействующий легализации доходов, полученных преступным путём, и финансированию терроризма." },
        { word: "РСЯ", trans: "Рекламная сеть Яндекса — партнёрская сеть сайтов и приложений, на которых размещается контекстная и медийная реклама Яндекса." },
        { word: "Рынок", trans: "Совокупность отношений купли-продажи между продавцами и покупателями определённого товара или услуги; также — физическое или виртуальное место торговли." },
        { word: "Рыночная экономика", trans: "Экономическая система, в которой решения о производстве, распределении и потреблении принимаются на основе спроса и предложения через механизм цен." },
        { word: "Санация", trans: "Оздоровление финансового состояния компании-должника в рамках процедуры банкротства с целью восстановления платёжеспособности и избежания ликвидации." },
        { word: "Санкции", trans: "Ограничительные меры экономического, политического или дипломатического характера, вводимые одним государством или группой государств против другого." },
        { word: "САПР", trans: "Система автоматизированного проектирования — программный комплекс для создания чертежей, 3D-моделей и технической документации (AutoCAD, SolidWorks)." },
        { word: "СБП", trans: "Система быстрых платежей — сервис Банка России, позволяющий физическим лицам мгновенно переводить деньги по номеру телефона между счетами в разных банках 24/7." },
        { word: "Сделка", trans: "Действия граждан и юридических лиц, направленные на установление, изменение или прекращение гражданских прав и обязанностей (договоры, односторонние акты)." },
        { word: "Скользящий график работы", trans: "Режим рабочего времени, при котором дни работы и отдыха смещаются по циклу, не совпадая с календарной неделей (например, 2 через 2)." },
        { word: "СКУД", trans: "Система контроля и управления доступом — комплекс технических средств для ограничения и регистрации входа/выхода людей и въезда/выезда транспорта на территорию." },
        { word: "СНИЛС", trans: "Страховой номер индивидуального лицевого счёта — уникальный идентификатор гражданина в системе пенсионного страхования РФ; зелёная карточка или электронный документ." },
        { word: "Собственник", trans: "Лицо, обладающее правом собственности на имущество: правом владения, пользования и распоряжения им по своему усмотрению." },
        { word: "СРО", trans: "Саморегулируемая организация — объединение субъектов предпринимательской деятельности, созданное для разработки и применения стандартов и правил в определённой отрасли." },
        { word: "Срочный трудовой договор", trans: "Трудовой договор, заключаемый на определённый срок (до 5 лет) при невозможности установить бессрочные отношения (сезонные работы, замена сотрудника, проект)." },
        { word: "Срок исковой давности", trans: "Период времени, в течение которого лицо может обратиться в суд за защитой своего нарушенного права (общий срок в РФ — 3 года)." },
        { word: "Стартап", trans: "Молодая компания, находящаяся в стадии развития и исследующая масштабируемую бизнес-модель в условиях высокой неопределённости." },
        { word: "Стейкинг", trans: "Staking — блокировка криптовалюты в кошельке для поддержки работы блокчейна (Proof-of-Stake) с получением вознаграждения в виде дополнительных монет." },
        { word: "Стейкхолдер", trans: "Заинтересованная сторона — любое лицо или группа, влияющие на деятельность компании или зависящие от неё (акционеры, сотрудники, клиенты, государство, местные сообщества)." },
        { word: "Сторителлинг", trans: "Storytelling — искусство рассказывания историй для передачи идей, ценностей или продвижения бренда; создаёт эмоциональную связь с аудиторией." },
        { word: "Стратегическое планирование", trans: "Процесс определения долгосрочных целей компании и путей их достижения с учётом внешней среды и внутренних ресурсов." },
        { word: "Стратегия компании", trans: "Общий план действий, определяющий направление развития организации, её конкурентные преимущества и распределение ресурсов для достижения миссии и целей." },
        { word: "Судебный пристав", trans: "Должностное лицо, обеспечивающее исполнение судебных актов и актов других органов (взыскание долгов, арест имущества, принудительное выселение)." },
        { word: "СУОТ", trans: "Система управления охраной труда — комплекс взаимосвязанных элементов (политика, цели, процедуры, ресурсы), направленный на сохранение жизни и здоровья работников." },
        { word: "Существенные условия договора", trans: "Условия, которые являются необходимыми и достаточными для заключения договора (предмет, условия, прямо указанные в законе как существенные)." },
        { word: "СФР", trans: "Социальный фонд России — единый государственный внебюджетный фонд, образованный в 2023 г. слиянием ПФР и ФСС; отвечает за пенсии, пособия и соцстрахование." },
        { word: "СЭДО", trans: "Система электронного документооборота — платформа для создания, хранения, маршрутизации и архивирования электронных документов внутри организации или между контрагентами." },
        { word: "Таможенный союз", trans: "Форма экономической интеграции, при которой страны-участницы отменяют таможенные пошлины во взаимной торговле и устанавливают единый таможенный тариф для третьих стран." },
        { word: "Тендер", trans: "Конкурентная процедура выбора поставщика товаров, работ или услуг, при которой побеждает участник, предложивший наилучшие условия (цена, качество, сроки)." },
        { word: "Тег", trans: "Метка, присваиваемая объекту (файлу, посту, товару) для классификации, поиска или отслеживания (хештег в соцсетях, UTM-тег в ссылке, мета-тег на сайте)." },
        { word: "Токен", trans: "Цифровая единица, выпущенная на базе существующего блокчейна (чаще Ethereum), представляющая право на актив, доступ к сервису или участие в проекте." },
        { word: "Транзакция", trans: "Операция перевода средств, ценных бумаг или данных между двумя сторонами; в блокчейне — запись о передаче криптоактивов." },
        { word: "Трейдинг", trans: "Trading — деятельность по купле-продаже финансовых инструментов (акций, валюты, деривативов) с целью получения прибыли от разницы цен." },
        { word: "Третейский суд", trans: "Негосударственный орган, избираемый сторонами для разрешения гражданского спора; решение третейского суда обязательно для сторон." },
        { word: "Трудовая книжка", trans: "Основной документ о трудовой деятельности и трудовом стаже работника; с 2021 г. ведётся в электронном виде (ЭТК), бумажная — по заявлению работника." },
        { word: "ТСД", trans: "Терминал сбора данных — портативное устройство со сканером штрихкодов, используемое на складах и в торговле для учёта товаров и инвентаризации." },
        { word: "Уведомление", trans: "Официальное сообщение, информирующее адресата о наступлении определённого события, изменении условий или необходимости совершить действие." },
        { word: "Унитарное предприятие", trans: "Коммерческая организация, не наделённая правом собственности на закреплённое за ней имущество (оно принадлежит учредителю — государству или муниципалитету)." },
        { word: "Управление персоналом", trans: "Система принципов и методов управления кадрами: подбор, адаптация, мотивация, развитие, оценка и удержание сотрудников для достижения целей организации." },
        { word: "Устав", trans: "Учредительный документ юридического лица, определяющий его наименование, цели, структуру управления, права и обязанности участников, порядок распределения прибыли." },
        { word: "Факторинг", trans: "Финансовая услуга, при которой фактор (банк или компания) покупает у поставщика его дебиторскую задолженность с дисконтом, предоставляя немедленное финансирование." },
        { word: "Факторы производства", trans: "Ресурсы, используемые для создания товаров и услуг: земля, труд, капитал, предпринимательские способности, информация." },
        { word: "Факторы спроса", trans: "Условия, влияющие на величину спроса: цена товара, доходы потребителей, цены на сопряжённые товары, вкусы и предпочтения, ожидания, число покупателей." },
        { word: "Фандрайзинг", trans: "Привлечение финансовых и иных ресурсов (денег, оборудования, волонтёрского труда) для реализации проекта, обычно некоммерческого или стартапа." },
        { word: "ФАС", trans: "Федеральная антимонопольная служба — орган, контролирующий соблюдение антимонопольного законодательства, рекламы, госзакупок и тарифов." },
        { word: "Фасилитация", trans: "Профессиональное ведение группового обсуждения или встречи фасилитатором для достижения консенсуса, генерации идей или принятия решения." },
        { word: "Федресурс", trans: "Единый федеральный реестр юридически значимых сведений о фактах деятельности юридических лиц, ИП и иных субъектов экономической деятельности." },
        { word: "ФИАС", trans: "Федеральная информационная адресная система — государственная база данных, содержащая актуальные сведения об адресах на территории РФ." },
        { word: "Фидбэк", trans: "Feedback — обратная связь от клиентов, пользователей или сотрудников о продукте, услуге или процессе; используется для улучшений." },
        { word: "Физическое лицо", trans: "Человек как субъект гражданских прав и обязанностей; может быть гражданином, иностранным гражданином или лицом без гражданства." },
        { word: "Финансовая система", trans: "Совокупность финансовых институтов (банки, биржи, страховые компании), инструментов и рынков, обеспечивающих движение денежных средств в экономике." },
        { word: "Фискальный накопитель", trans: "Шифровальное устройство внутри онлайн-кассы, которое хранит, шифрует и передаёт данные о расчётах в ФНС через оператора фискальных данных." },
        { word: "Фишинг", trans: "Вид интернет-мошенничества, при котором злоумышленники под видом доверенного отправителя выманивают у жертвы конфиденциальные данные (логины, пароли, данные карт)." },
        { word: "Форс-мажор", trans: "Обстоятельство непреодолимой силы (стихийное бедствие, война, пандемия), освобождающее сторону от ответственности за неисполнение обязательств по договору." },
        { word: "Франшиза", trans: "Право вести бизнес под известным брендом по готовой модели, передаваемое франчайзером франчайзи за паушальный взнос и роялти." },
        { word: "Фреймворк", trans: "Framework — программная или концептуальная структура, облегчающая разработку или решение задач (React, Scrum, Business Model Canvas)." },
        { word: "Фулфилмент", trans: "Комплекс операций по обработке заказов интернет-магазина: приём, хранение, комплектация, упаковка, маркировка и доставка товаров покупателям." },
        { word: "Фьючерсы", trans: "Стандартизированные биржевые контракты на покупку или продажу базового актива в будущем по цене, зафиксированной сегодня." },
        { word: "Хакатон", trans: "Hackathon — мероприятие, на котором команды разработчиков, дизайнеров и менеджеров за ограниченное время (обычно 24–72 часа) создают прототип программного продукта." },
        { word: "Хеджирование", trans: "Страхование финансовых рисков путём открытия компенсирующей позиции на бирже (например, покупка фьючерса для защиты от роста цены сырья)." },
        { word: "Ходатайство", trans: "Письменное или устное обращение к государственному органу или суду с просьбой о совершении определённых действий или принятии решения." },
        { word: "Холдинг", trans: "Компания, владеющая контрольными пакетами акций других предприятий и управляющая ими; сама холдинговая компания может не вести операционной деятельности." },
        { word: "Холодные продажи", trans: "Продажи, при которых первый контакт с потенциальным клиентом происходит без предварительной заявки или знакомства (холодные звонки, рассылки)." },
        { word: "Хостинг", trans: "Услуга предоставления дискового пространства и вычислительных ресурсов на сервере для размещения сайта или приложения в интернете." },
        { word: "Цена", trans: "Денежное выражение стоимости товара или услуги; количество денег, за которое продавец готов продать, а покупатель — купить единицу блага." },
        { word: "Ценные бумаги", trans: "Документы, удостоверяющие имущественные права, которые могут осуществляться или передаваться только при предъявлении этих документов (акции, облигации, векселя)." },
        { word: "Цифровизация", trans: "Внедрение цифровых технологий во все аспекты деятельности компании или государства для повышения эффективности, скорости и качества процессов." },
        { word: "Цифровой след", trans: "Совокупность данных, оставляемых пользователем в интернете: история поиска, покупки, геолокация, активность в соцсетях, комментарии." },
        { word: "Чистые активы", trans: "Разница между суммой активов компании и её обязательствами; показатель реального собственного капитала, доступного акционерам после погашения всех долгов." },
        { word: "Штамп", trans: "Реквизит, проставляемый на документах для подтверждения их статуса, даты, факта получения или обработки (штамп «Оплачено», «Входящий №»)." },
        { word: "Экспроприация", trans: "Принудительное изъятие имущества у собственника государством в общественных интересах с выплатой компенсации (в отличие от конфискации — безвозмездной)." },
        { word: "Электронная трудовая книжка", trans: "Цифровой формат трудовой книжки, ведущийся Пенсионным фондом (ныне СФР) на основе сведений, подаваемых работодателями; доступна работнику в личном кабинете." },
        { word: "Эмитент", trans: "Организация или государство, выпускающие ценные бумаги (акции, облигации) или денежные знаки в обращение." },
        { word: "ЭСФ", trans: "Электронный счёт-фактура — цифровой аналог бумажного счёта-фактуры, формируемый и передаваемый через оператора ЭДО; обязателен для НДС-плательщиков в РФ." },
        { word: "Юзабилити", trans: "Usability — степень удобства использования продукта, сайта или интерфейса: насколько легко, быстро и приятно пользователь достигает своей цели." },
        { word: "Юридическая ответственность", trans: "Обязанность лица претерпеть неблагоприятные последствия за совершённое правонарушение (уголовная, административная, гражданско-правовая, дисциплинарная)." },
        { word: "Юридическое лицо", trans: "Организация, имеющая обособленное имущество, отвечающая им по своим обязательствам, могущая от своего имени приобретать права, нести обязанности и быть истцом/ответчиком в суде." }
    ],
    topic4: [
        { word: "API", trans: "Application Programming Interface — интерфейс программирования приложений. Набор правил, позволяющий одним программам взаимодействовать с другими (например, сайт получает данные о погоде через API метеосервиса)." },
        { word: "Big Data", trans: "Большие данные — совокупность огромных массивов структурированной и неструктурированной информации, обрабатываемых для выявления закономерностей и трендов." },
        { word: "Cookie", trans: "Небольшой фрагмент данных, который веб-сайт сохраняет в браузере пользователя для запоминания настроек, авторизации или отслеживания поведения." },
        { word: "CRM-система", trans: "Система управления взаимоотношениями с клиентами. Программа для хранения данных о клиентах, истории взаимодействий и автоматизации продаж." },
        { word: "DBS", trans: "Delivery Business System — система управления доставкой; также может означать Database System (система баз данных) в IT-контексте." },
        { word: "ER-диаграмма", trans: "Entity-Relationship diagram — диаграмма «сущность-связь». Графическая модель данных, используемая при проектировании баз данных для отображения объектов и отношений между ними." },
        { word: "IP-адрес", trans: "Internet Protocol address — уникальный числовой идентификатор устройства в компьютерной сети, работающей по протоколу IP." },
        { word: "MRR", trans: "Monthly Recurring Revenue — ежемесячный повторяющийся доход. Ключевой показатель для SaaS-бизнесов и подписочных моделей." },
        { word: "P&L-отчет", trans: "Profit and Loss statement — отчёт о прибылях и убытках. Финансовый документ, показывающий доходы, расходы и чистую прибыль компании за период." },
        { word: "SMM-продвижение", trans: "Social Media Marketing — продвижение бренда, продукта или услуги через социальные сети." },
        { word: "USDT", trans: "Tether — стейблкоин, криптовалюта, курс которой привязан к доллару США (1 USDT ≈ 1 USD). Используется для сохранения стоимости в крипторынке." },
        { word: "VPN", trans: "Virtual Private Network — виртуальная частная сеть. Технология, создающая защищённое зашифрованное соединение через публичный интернет для анонимности и доступа к заблокированным ресурсам." },
        { word: "Искусственный интеллект", trans: "Artificial Intelligence (AI) — способность компьютерных систем имитировать человеческие когнитивные функции: обучение, решение задач, распознавание образов, принятие решений." },
        { word: "Инфографика", trans: "Визуальное представление сложной информации, данных или знаний в виде графиков, схем, диаграмм для быстрого и лёгкого восприятия." },
        { word: "Интерфейс", trans: "Совокупность средств и правил взаимодействия пользователя с программой, сайтом или устройством (кнопки, меню, экраны)." },
        { word: "Компьютерное зрение", trans: "Computer Vision — область ИИ, позволяющая компьютерам извлекать информацию из изображений и видео (распознавание лиц, объектов, текста)." },
        { word: "Машинное обучение", trans: "Machine Learning — подраздел ИИ, в котором алгоритмы учатся выявлять закономерности в данных и делать прогнозы без явного программирования правил." },
        { word: "Машиночитаемая доверенность", trans: "Электронная доверенность в формате XML, подписанная электронной подписью; используется для передачи полномочий между организациями в ЭДО." },
        { word: "Нейросеть", trans: "Искусственная нейронная сеть — математическая модель, вдохновлённая биологическими нейронами; основа глубокого обучения для распознавания образов, генерации текста и изображений." },
        { word: "Облачное хранилище", trans: "Сервис удалённого хранения данных на серверах провайдера с доступом через интернет (Google Drive, Яндекс.Диск)." },
        { word: "Операционная система", trans: "Комплекс программ, управляющих ресурсами компьютера и обеспечивающих взаимодействие пользователя с аппаратным обеспечением (Windows, macOS, Linux, Android)." },
        { word: "Программное обеспечение", trans: "Software — совокупность программ, процедур и правил, предназначенных для обработки данных и решения задач на компьютере." },
        { word: "Прокси-сервер", trans: "Промежуточный сервер, через который проходят запросы клиента к интернет-ресурсам; используется для анонимности, кэширования или обхода ограничений." },
        { word: "САПР", trans: "Система автоматизированного проектирования — программный комплекс для создания чертежей, 3D-моделей и технической документации (AutoCAD, SolidWorks)." },
        { word: "СКУД", trans: "Система контроля и управления доступом — комплекс технических средств для ограничения и регистрации входа/выхода людей и въезда/выезда транспорта." },
        { word: "Токен", trans: "Цифровая единица, выпущенная на базе существующего блокчейна, представляющая право на актив, доступ к сервису или участие в проекте." },
        { word: "ТСД", trans: "Терминал сбора данных — портативное устройство со сканером штрихкодов, используемое на складах и в торговле для учёта товаров." },
        { word: "Фискальный накопитель", trans: "Шифровальное устройство внутри онлайн-кассы, которое хранит, шифрует и передаёт данные о расчётах в ФНС через оператора фискальных данных." },
        { word: "Хостинг", trans: "Услуга предоставления дискового пространства и вычислительных ресурсов на сервере для размещения сайта или приложения в интернете." },
        { word: "Цифровизация", trans: "Внедрение цифровых технологий во все аспекты деятельности компании или государства для повышения эффективности, скорости и качества процессов." },
        { word: "Цифровой след", trans: "Совокупность данных, оставляемых пользователем в интернете: история поиска, покупки, геолокация, активность в соцсетях." },
        { word: "Электронная трудовая книжка", trans: "Цифровой формат трудовой книжки, ведущийся СФР на основе сведений, подаваемых работодателями; доступна работнику в личном кабинете." },
        { word: "ЭСФ", trans: "Электронный счёт-фактура — цифровой аналог бумажного счёта-фактуры, формируемый и передаваемый через оператора ЭДО; обязателен для НДС-плательщиков в РФ." }
    ],

    topic5: [
        { word: "Agile", trans: "Гибкая методология управления проектами, основанная на коротких циклах (спринтах), адаптивности и тесном взаимодействии команды с заказчиком." },
        { word: "HADI-цикл", trans: "Hypothesis-Action-Data-Insights — цикл проверки гипотез: выдвижение гипотезы, действие, сбор данных, выводы. Используется в agile-развитии продукта." },
        { word: "HR", trans: "Human Resources — управление персоналом; подразделение или функция, отвечающая за подбор, адаптацию, развитие и удержание сотрудников." },
        { word: "KPI", trans: "Key Performance Indicators — ключевые показатели эффективности. Измеримые метрики, отражающие успешность достижения целей компании, подразделения или сотрудника." },
        { word: "Аутсорсинг", trans: "Передача непрофильных бизнес-функций (бухгалтерия, IT, клининг) внешней специализированной компании по договору." },
        { word: "Аутстаффинг", trans: "Вывод персонала из штата компании-заказчика в штат провайдера с последующим предоставлением этих сотрудников заказчику для выполнения работ." },
        { word: "Бизнес-процесс", trans: "Совокупность взаимосвязанных действий, направленных на создание определённого продукта или услуги для внутреннего или внешнего клиента." },
        { word: "Должностная инструкция", trans: "Локальный нормативный акт, определяющий обязанности, права, ответственность и квалификационные требования к работнику на конкретной должности." },
        { word: "Испытательный срок", trans: "Период в начале трудовых отношений, устанавливаемый для проверки соответствия работника поручаемой работе (обычно до 3 месяцев)." },
        { word: "Итерация", trans: "Повторение цикла действий с целью приближения к желаемому результату; в agile — короткий рабочий цикл (спринт), по итогам которого создаётся инкремент продукта." },
        { word: "Кадровый резерв", trans: "Группа сотрудников, прошедших отбор и подготовку для замещения ключевых должностей в компании в случае вакансии или расширения." },
        { word: "Категории персонала", trans: "Группы работников, выделяемые по характеру труда: руководители, специалисты, служащие, рабочие." },
        { word: "Коворкинг", trans: "Общее офисное пространство, где независимые профессионалы, фрилансеры и стартапы арендуют рабочие места и пользуются общей инфраструктурой." },
        { word: "Комплаенс", trans: "Система внутреннего контроля, обеспечивающая соответствие деятельности компании законодательству, отраслевым стандартам и внутренним политикам." },
        { word: "Коуч", trans: "Специалист, помогающий клиенту достичь личных или профессиональных целей через серию вопросов, раскрытие потенциала и построение плана действий." },
        { word: "Менеджер", trans: "Специалист, осуществляющий управление определённым направлением, проектом или командой в организации." },
        { word: "Нормирование труда", trans: "Установление мер труда (норм времени, выработки, обслуживания) для рационального использования рабочего времени и оценки производительности." },
        { word: "Онбординг", trans: "Процесс адаптации нового сотрудника или пользователя продукта: обучение, знакомство с правилами, помощь в первых шагах." },
        { word: "Оптимизация бизнес-процессов", trans: "Анализ и улучшение рабочих процессов компании для повышения эффективности, снижения затрат и устранения потерь." },
        { word: "Организационная структура предприятия", trans: "Схема соподчинения подразделений, должностей и функций в компании, определяющая иерархию и распределение ответственности." },
        { word: "Отдел кадров", trans: "Подразделение компании, отвечающее за подбор, оформление, учёт, развитие и увольнение персонала, а также ведение кадровой документации." },
        { word: "Отпуск", trans: "Ежегодный оплачиваемый перерыв в работе, предоставляемый работнику для отдыха и восстановления трудоспособности (минимум 28 календарных дней в РФ)." },
        { word: "Повышение квалификации", trans: "Обучение работников с целью обновления и расширения их профессиональных знаний и навыков в соответствии с требованиями должности." },
        { word: "Производственный календарь", trans: "Официальный документ, определяющий нормы рабочего времени, выходные и праздничные дни на год; используется для расчёта зарплаты и графиков." },
        { word: "Разработка продукта", trans: "Product Development — процесс создания нового товара или услуги: от идеи и исследования рынка до запуска в производство и вывода на рынок." },
        { word: "Рекомендательное письмо", trans: "Документ, характеризующий профессиональные и личные качества бывшего сотрудника, выдаваемый предыдущим работодателем по запросу." },
        { word: "Релокация", trans: "Переезд сотрудника в другой город или страну по инициативе работодателя с компенсацией расходов на переезд, жильё и оформление документов." },
        { word: "Скользящий график работы", trans: "Режим рабочего времени, при котором дни работы и отдыха смещаются по циклу, не совпадая с календарной неделей (например, 2 через 2)." },
        { word: "Срочный трудовой договор", trans: "Трудовой договор, заключаемый на определённый срок (до 5 лет) при невозможности установить бессрочные отношения." },
        { word: "Стартап", trans: "Молодая компания, находящаяся в стадии развития и исследующая масштабируемую бизнес-модель в условиях высокой неопределённости." },
        { word: "Стейкхолдер", trans: "Заинтересованная сторона — любое лицо или группа, влияющие на деятельность компании или зависящие от неё (акционеры, сотрудники, клиенты, государство)." },
        { word: "СУОТ", trans: "Система управления охраной труда — комплекс взаимосвязанных элементов, направленный на сохранение жизни и здоровья работников." },
        { word: "Управление персоналом", trans: "Система принципов и методов управления кадрами: подбор, адаптация, мотивация, развитие, оценка и удержание сотрудников." },
        { word: "Формы организации труда", trans: "Способы разделения и кооперации труда в компании: бригадная, индивидуальная, поточная, проектная и др." },
        { word: "Фреймворк", trans: "Framework — программная или концептуальная структура, облегчающая разработку или решение задач (React, Scrum, Business Model Canvas)." },
        { word: "Хакатон", trans: "Hackathon — мероприятие, на котором команды разработчиков, дизайнеров и менеджеров за ограниченное время создают прототип программного продукта." },
        { word: "Штатное расписание", trans: "Локальный нормативный акт, содержащий перечень структурных подразделений, должностей, количества штатных единиц и окладов." }
    ],

    topic6: [
        { word: "IPO", trans: "Initial Public Offering — первичное публичное размещение акций компании на бирже, позволяющее привлечь капитал от широкого круга инвесторов." },
        { word: "IRR", trans: "Internal Rate of Return — внутренняя норма доходности. Ставка дисконтирования, при которой чистая приведённая стоимость (NPV) проекта равна нулю." },
        { word: "Альтернативная стоимость", trans: "Ценность наилучшей из упущенных возможностей; то, чем жертвует субъект, выбирая один вариант вместо другого." },
        { word: "Андеррайтинг", trans: "Процедура оценки рисков и определения условий выпуска ценных бумаг; андеррайтер берёт на себя обязательства по размещению выпуска." },
        { word: "Аукцион", trans: "Публичная продажа товаров, ценных бумаг или имущества, при которой победителем становится участник, предложивший наивысшую цену." },
        { word: "Байбэк", trans: "Buyback — обратный выкуп компанией собственных акций с рынка для сокращения их количества, повышения цены и EPS." },
        { word: "Банк", trans: "Финансовая организация, имеющая лицензию ЦБ на привлечение вкладов, размещение кредитов и проведение расчётов." },
        { word: "Банк России", trans: "Центральный банк Российской Федерации — мегарегулятор финансового рынка, отвечающий за денежно-кредитную политику, надзор за банками и эмиссию рубля." },
        { word: "Бартер", trans: "Прямой обмен товарами или услугами между сторонами без использования денег." },
        { word: "Биржа", trans: "Организованный рынок, на котором проводятся торги стандартизированными активами (акциями, облигациями, валютой, товарами) по установленным правилам." },
        { word: "БРИКС", trans: "Межгосударственное объединение Бразилии, России, Индии, Китая и ЮАР (с 2024 г. расширено), созданное для экономического и политического сотрудничества." },
        { word: "Валюта", trans: "Денежная единица, используемая в качестве меры стоимости и средства платежа в стране или группе стран." },
        { word: "Валютный контроль", trans: "Система мер государства по регулированию операций с иностранной валютой для предотвращения незаконного вывода капитала." },
        { word: "Вексель", trans: "Письменное долговое обязательство строго установленной формы, дающее его владельцу право требовать от должника уплаты определённой суммы в установленный срок." },
        { word: "Венчур", trans: "Venture capital — рисковый капитал, инвестируемый в инновационные стартапы на ранних стадиях в обмен на долю в компании." },
        { word: "Виды экономической деятельности", trans: "Классификация хозяйственной деятельности организаций и ИП по ОКВЭД; определяет применяемые налоговые режимы, тарифы взносов и отчётность." },
        { word: "Волатильность", trans: "Степень изменчивости цены финансового инструмента или рынка за определённый период. Высокая волатильность означает высокие риски и возможности." },
        { word: "ВВП", trans: "Валовой внутренний продукт — рыночная стоимость всех конечных товаров и услуг, произведённых на территории страны за год." },
        { word: "Девальвация", trans: "Официальное снижение курса национальной валюты по отношению к иностранным валютам, проводимое центральным банком." },
        { word: "Денежная эмиссия", trans: "Выпуск в обращение наличных или безналичных денег центральным банком, увеличивающий общую денежную массу в экономике." },
        { word: "Денежно-кредитная политика", trans: "Совокупность мер центрального банка по регулированию денежной массы, процентных ставок и инфляции для обеспечения стабильности экономики." },
        { word: "Дефляция", trans: "Устойчивое снижение общего уровня цен на товары и услуги в экономике; противоположность инфляции." },
        { word: "Дефолт", trans: "Невыполнение заёмщиком (государством или компанией) своих обязательств по выплате долга или процентов по нему." },
        { word: "Дивиденды", trans: "Часть чистой прибыли акционерного общества, распределяемая между акционерами пропорционально количеству принадлежащих им акций." },
        { word: "Закон спроса и предложения", trans: "Экономический закон: при прочих равных рост цены снижает спрос и увеличивает предложение; равновесная цена устанавливается при равенстве спроса и предложения." },
        { word: "Инвестиции", trans: "Вложение капитала в объекты предпринимательской деятельности с целью получения прибыли или достижения иного полезного эффекта." },
        { word: "Инфляция", trans: "Устойчивый рост общего уровня цен на товары и услуги, приводящий к снижению покупательной способности денег." },
        { word: "Капитализация", trans: "Рыночная стоимость компании, рассчитываемая как произведение текущей цены одной акции на общее количество выпущенных акций." },
        { word: "Клиринг", trans: "Система безналичных расчётов между банками или участниками биржи, основанная на взаимном зачёте требований и обязательств." },
        { word: "Концессия", trans: "Договор, по которому государство передаёт частной компании право на эксплуатацию объектов инфраструктуры или природных ресурсов на определённый срок за плату." },
        { word: "Котировки", trans: "Цены, по которым готовы купить (bid) или продать (ask) ценную бумагу, валюту или товар на бирже в данный момент." },
        { word: "Криптовалюта", trans: "Цифровая валюта, функционирующая на базе технологии блокчейн без центрального эмитента; используется как средство обмена или инвестиционный актив." },
        { word: "Лизинг", trans: "Финансовая аренда: лизинговая компания приобретает имущество по выбору клиента и передаёт ему во временное пользование за плату с правом последующего выкупа." },
        { word: "Ликвидность", trans: "Способность актива быть быстро проданным по рыночной цене без существенной потери стоимости; также — способность компании своевременно погашать обязательства." },
        { word: "Листинг", trans: "Процедура допуска ценных бумаг к торгам на бирже после проверки эмитента на соответствие требованиям биржи." },
        { word: "Маржинальная торговля", trans: "Торговля с использованием кредитного плеча: трейдер вносит часть средств (маржу), а брокер предоставляет остальное для увеличения объёма сделки." },
        { word: "МВФ", trans: "Международный валютный фонд — международная организация, содействующая стабильности валютных курсов, предоставляющая кредиты странам с проблемами платёжного баланса." },
        { word: "Монополия", trans: "Рыночная структура, при которой одна компания контролирует весь или почти весь рынок определённого товара, диктуя цены и условия." },
        { word: "Национальный режим", trans: "Принцип, согласно которому иностранным товарам и поставщикам предоставляются те же условия, что и отечественным, в рамках госзакупок и торговли." },
        { word: "Облигации", trans: "Долговые ценные бумаги, удостоверяющие право владельца на получение от эмитента номинальной стоимости и фиксированного процента (купона) в установленные сроки." },
        { word: "Овердрафт", trans: "Краткосрочный кредит, предоставляемый банком при недостатке средств на расчётном счёте клиента для покрытия текущих платежей." },
        { word: "Овернайт", trans: "Однодневная межбанковская ставка, по которой банки кредитуют друг друга на ночь для поддержания ликвидности." },
        { word: "Олигополия", trans: "Рыночная структура, при которой несколько крупных компаний контролируют большую часть рынка и могут влиять на цены и условия." },
        { word: "Опцион", trans: "Производный финансовый инструмент, дающий право (но не обязанность) купить или продать базовый актив по заранее определённой цене в будущем." },
        { word: "ОФЗ", trans: "Облигации федерального займа — государственные ценные бумаги РФ, выпускаемые Минфином для финансирования дефицита бюджета; считаются надёжным инструментом." },
        { word: "РЕПО", trans: "Repurchase agreement — сделка, при которой одна сторона продаёт ценные бумаги другой с обязательством выкупить их обратно через определённый срок по заранее оговорённой цене." },
        { word: "Рецессия", trans: "Спад экономической активности, характеризующийся снижением ВВП, производства, занятости и доходов в течение как минимум двух кварталов подряд." },
        { word: "Рынок", trans: "Совокупность отношений купли-продажи между продавцами и покупателями определённого товара или услуги; также — физическое или виртуальное место торговли." },
        { word: "Рыночная экономика", trans: "Экономическая система, в которой решения о производстве, распределении и потреблении принимаются на основе спроса и предложения через механизм цен." },
        { word: "Санкции", trans: "Ограничительные меры экономического, политического или дипломатического характера, вводимые одним государством или группой государств против другого." },
        { word: "Сделка", trans: "Действия граждан и юридических лиц, направленные на установление, изменение или прекращение гражданских прав и обязанностей." },
        { word: "Спрос", trans: "Количество товара или услуги, которое покупатели готовы и способны приобрести по определённой цене за определённый период." },
        { word: "Стагнация", trans: "Застой в экономике, характеризующийся отсутствием роста ВВП, высоким уровнем безработицы и низкой инвестиционной активностью." },
        { word: "Стагфляция", trans: "Сочетание стагнации (спада производства) и высокой инфляции; редкое и опасное состояние экономики." },
        { word: "Таможенный союз", trans: "Форма экономической интеграции, при которой страны-участницы отменяют таможенные пошлины во взаимной торговле и устанавливают единый таможенный тариф для третьих стран." },
        { word: "Тендер", trans: "Конкурентная процедура выбора поставщика товаров, работ или услуг, при которой побеждает участник, предложивший наилучшие условия." },
        { word: "Транзакция", trans: "Операция перевода средств, ценных бумаг или данных между двумя сторонами; в блокчейне — запись о передаче криптоактивов." },
        { word: "Трейдинг", trans: "Trading — деятельность по купле-продаже финансовых инструментов (акций, валюты, деривативов) с целью получения прибыли от разницы цен." },
        { word: "Факторинг", trans: "Финансовая услуга, при которой фактор (банк или компания) покупает у поставщика его дебиторскую задолженность с дисконтом, предоставляя немедленное финансирование." },
        { word: "Факторы производства", trans: "Ресурсы, используемые для создания товаров и услуг: земля, труд, капитал, предпринимательские способности, информация." },
        { word: "Факторы спроса", trans: "Условия, влияющие на величину спроса: цена товара, доходы потребителей, цены на сопряжённые товары, вкусы и предпочтения, ожидания, число покупателей." },
        { word: "Франшиза", trans: "Право вести бизнес под известным брендом по готовой модели, передаваемое франчайзером франчайзи за паушальный взнос и роялти." },
        { word: "Фьючерсы", trans: "Стандартизированные биржевые контракты на покупку или продажу базового актива в будущем по цене, зафиксированной сегодня." },
        { word: "Хеджирование", trans: "Страхование финансовых рисков путём открытия компенсирующей позиции на бирже (например, покупка фьючерса для защиты от роста цены сырья)." },
        { word: "Ценные бумаги", trans: "Документы, удостоверяющие имущественные права, которые могут осуществляться или передаваться только при предъявлении этих документов (акции, облигации, векселя)." },
        { word: "Цена", trans: "Денежное выражение стоимости товара или услуги; количество денег, за которое продавец готов продать, а покупатель — купить единицу блага." },
        { word: "Экспроприация", trans: "Принудительное изъятие имущества у собственника государством в общественных интересах с выплатой компенсации." },
        { word: "Эмитент", trans: "Организация или государство, выпускающие ценные бумаги (акции, облигации) или денежные знаки в обращение." }
    ]
};
